//! `filmMode` 是持续状态，不是一次性演出；计划里要保留启用/关闭的时间点。

use std::fs;
use std::path::Path;

use webgal_video_export::api::{ExportOptions, build_plan};

fn write(root: &Path, relative: &str, text: &str) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, text).expect("write fixture");
}

#[test]
fn film_mode_changes_state_at_statement_time() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", "Game_name:Film;\n");
    write(
        root,
        "game/scene/start.txt",
        "\
filmMode:on;
say:first;
wait:100;
filmMode:none;
say:second;
end;
",
    );

    let plan = build_plan(&ExportOptions::new(root)).expect("build plan");
    assert_eq!(plan.film.len(), 2, "只记录真正的状态变化");
    assert_eq!(plan.film[0].t_us, 0);
    assert!(plan.film[0].enabled);
    assert_eq!(plan.film[1].t_us, plan.texts[1].start_us);
    assert!(!plan.film[1].enabled);
}
